def factorial(n: int) -> int:
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def fibonacci_rec(n: int) -> int:
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    return fibonacci_rec(n - 1) + fibonacci_rec(n - 2)

def ackermann(m: int, n: int) -> int:
    if m == 0:
        return n + 1
    elif m > 0 and n == 0:
        return ackermann(m - 1, 1)
    return ackermann(m - 1, ackermann(m, n - 1))

def gcd(a: int, b: int) -> int:
    if b == 0:
        return a
    return gcd(b, a % b)

def lcm(a: int, b: int) -> int:
    def gcd_inner(x: int, y: int) -> int:
        while y != 0:
            x, y = y, x % y
        return x
    return abs(a * b) // gcd_inner(a, b)

def hanoi(n: int, source: str, target: str, auxiliary: str, moves: list) -> None:
    if n > 0:
        hanoi(n - 1, source, auxiliary, target, moves)
        moves.append((source, target))
        hanoi(n - 1, auxiliary, target, source, moves)

def power_rec(base: float, exp: int) -> float:
    if exp == 0:
        return 1.0
    elif exp < 0:
        return 1.0 / power_rec(base, -exp)
    elif exp % 2 == 0:
        half = power_rec(base, exp // 2)
        return half * half
    return base * power_rec(base, exp - 1)

def sum_digits(n: int) -> int:
    if n < 10:
        return n
    return (n % 10) + sum_digits(n // 10)

def reverse_str(s: str) -> str:
    if len(s) <= 1:
        return s
    return reverse_str(s[1:]) + s[0]

def is_palindrome(s: str) -> bool:
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        return False
    return is_palindrome(s[1:-1])

def count_vowels(s: str) -> int:
    if not s:
        return 0
    is_vowel = 1 if s[0].lower() in 'aeiou' else 0
    return is_vowel + count_vowels(s[1:])

def binary_search_rec(arr: list, target: int, low: int, high: int) -> int:
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] > target:
        return binary_search_rec(arr, target, low, mid - 1)
    return binary_search_rec(arr, target, mid + 1, high)

def flatten(nested: list) -> list:
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def max_depth(root) -> int:
    if root is None:
        return 0
    left = max_depth(root.left)
    right = max_depth(root.right)
    return 1 + max(left, right)

def min_depth(root) -> int:
    if root is None:
        return 0
    if root.left is None:
        return 1 + min_depth(root.right)
    if root.right is None:
        return 1 + min_depth(root.left)
    return 1 + min(min_depth(root.left), min_depth(root.right))

def count_nodes(root) -> int:
    if root is None:
        return 0
    return 1 + count_nodes(root.left) + count_nodes(root.right)

def is_same_tree(p, q) -> bool:
    if not p and not q:
        return True
    if not p or not q or p.val != q.val:
        return False
    return is_same_tree(p.left, q.left) and is_same_tree(p.right, q.right)

def invert_tree(root):
    if root is None:
        return None
    root.left, root.right = invert_tree(root.right), invert_tree(root.left)
    return root

def subsets(nums: list) -> list:
    res = []
    def backtrack(start: int, curr: list):
        res.append(list(curr))
        for i in range(start, len(nums)):
            curr.append(nums[i])
            backtrack(i + 1, curr)
            curr.pop()
    backtrack(0, [])
    return res

def permutations(nums: list) -> list:
    res = []
    def backtrack(curr: list, remaining: list):
        if not remaining:
            res.append(list(curr))
            return
        for i in range(len(remaining)):
            backtrack(curr + [remaining[i]], remaining[:i] + remaining[i+1:])
    backtrack([], nums)
    return res

def bubble_sort(arr: list) -> list:
    a = list(arr)
    n = len(a)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
    return a

def selection_sort(arr: list) -> list:
    a = list(arr)
    n = len(a)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if a[j] < a[min_idx]:
                min_idx = j
        a[i], a[min_idx] = a[min_idx], a[i]
    return a

def insertion_sort(arr: list) -> list:
    a = list(arr)
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

def quick_sort(arr: list) -> list:
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(left) + middle + quick_sort(right)

def counting_sort(arr: list, max_val: int) -> list:
    count = [0] * (max_val + 1)
    for num in arr:
        count[num] += 1
    res = []
    for val, c in enumerate(count):
        res.extend([val] * c)
    return res

def linear_search(arr: list, target: int) -> int:
    for idx, item in enumerate(arr):
        if item == target:
            return idx
    return -1

def binary_search(arr: list, target: int) -> int:
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def find_kth_largest(nums: list, k: int) -> int:
    nums_sorted = sorted(nums, reverse=True)
    return nums_sorted[k - 1]

def find_peak_element(nums: list) -> int:
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[mid + 1]:
            right = mid
        else:
            left = mid + 1
    return left

def search_rotated(nums: list, target: int) -> int:
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

def two_sum_sorted(numbers: list, target: int) -> list:
    low, high = 0, len(numbers) - 1
    while low < high:
        total = numbers[low] + numbers[high]
        if total == target:
            return [low + 1, high + 1]
        elif total < target:
            low += 1
        else:
            high -= 1
    return []

def three_sum(nums: list) -> list:
    nums.sort()
    res = []
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l, r = i + 1, len(nums) - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                res.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l + 1]:
                    l += 1
                while l < r and nums[r] == nums[r - 1]:
                    r -= 1
                l += 1
                r -= 1
    return res

def fib_dp(n: int) -> int:
    if n <= 1:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

def climb_stairs(n: int) -> int:
    if n <= 2:
        return n
    first, second = 1, 2
    for _ in range(3, n + 1):
        first, second = second, first + second
    return second

def knapsack(weights: list, values: list, capacity: int) -> int:
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]
    return dp[n][capacity]

def lcs(text1: str, text2: str) -> int:
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

def edit_distance(word1: str, word2: str) -> int:
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

def coin_change(coins: list, amount: int) -> int:
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)
    return int(dp[amount]) if dp[amount] != float('inf') else -1

def length_of_lis(nums: list) -> int:
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def max_subarray(nums: list) -> int:
    max_current = max_global = nums[0]
    for x in nums[1:]:
        max_current = max(x, max_current + x)
        if max_current > max_global:
            max_global = max_current
    return max_global

def rob(nums: list) -> int:
    prev1 = prev2 = 0
    for num in nums:
        prev1, prev2 = max(prev2 + num, prev1), prev1
    return prev1

def unique_paths(m: int, n: int) -> int:
    row = [1] * n
    for _ in range(m - 1):
        new_row = [1] * n
        for j in range(1, n):
            new_row[j] = new_row[j - 1] + row[j]
        row = new_row
    return row[-1]

def min_path_sum(grid: list) -> int:
    m, n = len(grid), len(grid[0])
    for i in range(m):
        for j in range(n):
            if i == 0 and j > 0:
                grid[i][j] += grid[i][j - 1]
            elif j == 0 and i > 0:
                grid[i][j] += grid[i - 1][j]
            elif i > 0 and j > 0:
                grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])
    return grid[m - 1][n - 1]

def can_partition(nums: list) -> bool:
    total = sum(nums)
    if total % 2 != 0:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]
    return dp[target]

def rod_cut(price: list, n: int) -> int:
    val = [0 for _ in range(n + 1)]
    for i in range(1, n + 1):
        max_val = -1
        for j in range(i):
            max_val = max(max_val, price[j] + val[i - j - 1])
        val[i] = max_val
    return val[n]

def bfs(graph: dict, start_node: str) -> list:
    visited = set()
    queue = [start_node]
    res = []
    while queue:
        node = queue.pop(0)
        if node not in visited:
            visited.add(node)
            res.append(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    queue.append(neighbor)
    return res

def dfs(graph: dict, node: str, visited: set = None) -> list:
    if visited is None:
        visited = set()
    res = []
    if node not in visited:
        visited.add(node)
        res.append(node)
        for neighbor in graph.get(node, []):
            res.extend(dfs(graph, neighbor, visited))
    return res

def dijkstra(graph: dict, start: str) -> dict:
    import heapq
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    pq = [(0, start)]
    while pq:
        curr_dist, curr_node = heapq.heappop(pq)
        if curr_dist > distances[curr_node]:
            continue
        for neighbor, weight in graph[curr_node].items():
            dist = curr_dist + weight
            if dist < distances[neighbor]:
                distances[neighbor] = dist
                heapq.heappush(pq, (dist, neighbor))
    return distances

def topological_sort(num_courses: int, prerequisites: list) -> list:
    adj = {i: [] for i in range(num_courses)}
    in_degree = [0] * num_courses
    for dest, src in prerequisites:
        adj[src].append(dest)
        in_degree[dest] += 1
    queue = [i for i in range(num_courses) if in_degree[i] == 0]
    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return order if len(order) == num_courses else []

def has_cycle(graph: dict) -> bool:
    visited = set()
    rec_stack = set()
    def dfs_cycle(node: str) -> bool:
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if dfs_cycle(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True
        rec_stack.remove(node)
        return False
    for node in graph:
        if node not in visited:
            if dfs_cycle(node):
                return True
    return False

def inorder(root) -> list:
    if not root:
        return []
    return inorder(root.left) + [root.val] + inorder(root.right)

def preorder(root) -> list:
    if not root:
        return []
    return [root.val] + preorder(root.left) + preorder(root.right)

def postorder(root) -> list:
    if not root:
        return []
    return postorder(root.left) + postorder(root.right) + [root.val]

def is_valid_bst(root, low=float('-inf'), high=float('inf')) -> bool:
    if not root:
        return True
    if not (low < root.val < high):
        return False
    return is_valid_bst(root.left, low, root.val) and is_valid_bst(root.right, root.val, high)

def lca_bst(root, p, q):
    if root.val > p.val and root.val > q.val:
        return lca_bst(root.left, p, q)
    elif root.val < p.val and root.val < q.val:
        return lca_bst(root.right, p, q)
    return root

def count_components(n: int, edges: list) -> int:
    parent = list(range(n))
    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x: int, y: int) -> bool:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False
    count = n
    for u, v in edges:
        if union(u, v):
            count -= 1
    return count

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sieve(limit: int) -> list:
    is_p = [True] * (limit + 1)
    is_p[0] = is_p[1] = False
    for p in range(2, int(limit**0.5) + 1):
        if is_p[p]:
            for i in range(p * p, limit + 1, p):
                is_p[i] = False
    return [p for p in range(limit + 1) if is_p[p]]

def prime_factors(n: int) -> list:
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def matmul(A: list, B: list) -> list:
    rows_A, cols_A = len(A), len(A[0])
    rows_B, cols_B = len(B), len(B[0])
    if cols_A != rows_B:
        raise ValueError('Incompatible matrix dimensions')
    C = [[0] * cols_B for _ in range(rows_A)]
    for i in range(rows_A):
        for j in range(cols_B):
            for k in range(cols_A):
                C[i][j] += A[i][k] * B[k][j]
    return C

def collatz_steps(n: int) -> int:
    steps = 0
    while n > 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def generate_pascal(num_rows: int) -> list:
    triangle = []
    for i in range(num_rows):
        row = [1] * (i + 1)
        for j in range(1, i):
            row[j] = triangle[i - 1][j - 1] + triangle[i - 1][j]
        triangle.append(row)
    return triangle

def mod_exp(base: int, exp: int, mod: int) -> int:
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp = exp // 2
        base = (base * base) % mod
    return result

def catalan_number(n: int) -> int:
    c = 1
    for i in range(n):
        c = c * 2 * (2 * i + 1) // (i + 2)
    return c

def roman_to_int(s: str) -> int:
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_val = 0
    for char in reversed(s):
        curr_val = roman_map[char]
        if curr_val >= prev_val:
            total += curr_val
        else:
            total -= curr_val
        prev_val = curr_val
    return total

def int_to_roman(num: int) -> str:
    val_map = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
    roman = []
    for val, sym in val_map:
        while num >= val:
            roman.append(sym)
            num -= val
    return ''.join(roman)

def sqrt_newton(n: float, tolerance: float = 1e-7) -> float:
    x = n
    while True:
        root = 0.5 * (x + (n / x))
        if abs(root - x) < tolerance:
            return root
        x = root

def rle_encode(text: str) -> str:
    if not text:
        return ''
    encoded = []
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            encoded.append(f'{count}{text[i - 1]}')
            count = 1
    encoded.append(f'{count}{text[-1]}')
    return ''.join(encoded)

def rle_decode(encoded: str) -> str:
    result = []
    count_str = ''
    for char in encoded:
        if char.isdigit():
            count_str += char
        else:
            count = int(count_str) if count_str else 1
            result.append(char * count)
            count_str = ''
    return ''.join(result)

def caesar_cipher(text: str, shift: int) -> str:
    res = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = chr((ord(char) - base + shift) % 26 + base)
            res.append(shifted)
        else:
            res.append(char)
    return ''.join(res)

def vigenere(text: str, key: str) -> str:
    res = []
    key_len = len(key)
    for i, char in enumerate(text):
        if char.isalpha():
            shift = ord(key[i % key_len].lower()) - ord('a')
            base = ord('A') if char.isupper() else ord('a')
            res.append(chr((ord(char) - base + shift) % 26 + base))
        else:
            res.append(char)
    return ''.join(res)

def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}
    for char in s:
        if char in mapping:
            top = stack.pop() if stack else '#'
            if mapping[char] != top:
                return False
        else:
            stack.append(char)
    return not stack

def length_of_longest_substring(s: str) -> int:
    char_index = {}
    max_len = 0
    start = 0
    for end, char in enumerate(s):
        if char in char_index and char_index[char] >= start:
            start = char_index[char] + 1
        char_index[char] = end
        max_len = max(max_len, end - start + 1)
    return max_len

def group_anagrams(strs: list) -> list:
    from collections import defaultdict
    ans = defaultdict(list)
    for s in strs:
        ans[tuple(sorted(s))].append(s)
    return list(ans.values())

def rabin_karp(pattern: str, text: str, prime: int = 101) -> list:
    m, n = len(pattern), len(text)
    if m > n:
        return []
    p_hash = sum(ord(pattern[i]) * (prime**i) for i in range(m))
    t_hash = sum(ord(text[i]) * (prime**i) for i in range(m))
    matches = []
    for i in range(n - m + 1):
        if p_hash == t_hash and text[i:i + m] == pattern:
            matches.append(i)
        if i < n - m:
            t_hash = (t_hash - ord(text[i])) // prime + ord(text[i + m]) * (prime**(m - 1))
    return matches

class SimpleStack:
    def __init__(self):
        self.items = []
    def push(self, item):
        self.items.append(item)
    def pop(self):
        if not self.items:
            raise IndexError('pop from empty stack')
        return self.items.pop()
    def is_empty(self):
        return len(self.items) == 0

class SimpleQueue:
    def __init__(self):
        self.items = []
    def enqueue(self, item):
        self.items.append(item)
    def dequeue(self):
